    /* Boot background keyed off the theme class (set by the script above, before paint) so the
       splash is the exact app color from frame 1 — no flash, and no dependency on inline styles
       that the app may clear. Values mirror the app's --background / --foreground. */
    html { background: #0d0e12; }
    html.light { background: #f7f7f7; }
    body { background: #0d0e12; display: flex; align-items: center; justify-content: center; min-height: 100vh; font-family: -apple-system, BlinkMacSystemFont, sans-serif; }
    html.light body { background: #f7f7f7; }
    #__bundler_loading { display: none !important; }
    /* Plain themed backdrop during unpack — no logo, so a reload shows a calm solid colour
       (not a logo that pops in and vanishes) until the app content paints. */
    #__bundler_thumbnail { position: fixed; inset: 0; background: #0d0e12; z-index: 9999;
      display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; }
    html.light #__bundler_thumbnail { background: #f7f7f7; }
    /* SPLASH_V1 - branded unpack screen instead of a bare black frame */
    #__bundler_thumbnail .dk-splash-title { font: 800 22px/1.2 -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: #ffffff; letter-spacing: -0.02em; animation: dk-splash-pulse 1.4s ease-in-out infinite; }
    #__bundler_thumbnail .dk-splash-title b { color: #6ea8ff; font-weight: 800; }
    html.light #__bundler_thumbnail .dk-splash-title { color: #15181f; }
    html.light #__bundler_thumbnail .dk-splash-title b { color: #2f7bff; }
    #__bundler_thumbnail .dk-splash-bar { width: 120px; height: 3px; border-radius: 999px;
      background: rgba(255,255,255,.10); overflow: hidden; position: relative; }
    html.light #__bundler_thumbnail .dk-splash-bar { background: rgba(0,0,0,.08); }
    #__bundler_thumbnail .dk-splash-bar::before { content: ''; position: absolute; top: 0; left: -40%;
      width: 40%; height: 100%; border-radius: 999px; background: #2f7bff;
      animation: dk-splash-slide 1.1s ease-in-out infinite; }
    @keyframes dk-splash-pulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: .72; transform: scale(.96); } }
    @keyframes dk-splash-slide { 0% { left: -40%; } 100% { left: 100%; } }
    html.light #__bundler_thumbnail { background: #f7f7f7; }
