data_extract: {
 "url": "https://keypool.duskyr.com",
 "status": 200,
 "size": 12933,
 "content_type": "text/html; charset=utf-8",
 "response_headers": {
  "Server": "nginx"
 },
 "redirected_to": "https://keypool.duskyr.com/",
 "redirect_status": null,
 "text": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>KeyPool — OpenAI Router</title>
<style>
  :root{
    --bg:#0d1117; --panel:#161b22; --panel2:#1c2230; --border:#2a3240;
    --text:#e6edf3; --dim:#8b949e; --accent:#3b82f6;
    --live:#2ea043; --dead:#f85149; --limited:#d29922;
  }
  *{box-sizing:border-box}
  body{margin:0;font:14px/1.5 -apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--text)}
  header{display:flex;align-items:center;gap:16px;padding:14px 22px;border-bottom:1px solid var(--border);background:var(--panel)}
  header h1{font-size:17px;margin:0;font-weight:650}
  .logo{width:26px;height:26px;border-radius:7px;background:linear-gradient(135deg,#3b82f6,#22d3ee);display:grid;place-items:center;font-weight:800;color:#06121f}
  .spacer{flex:1}
  .pill{padding:4px 10px;border-radius:999px;font-size:12px;font-weight:600;border:1px solid var(--border)}
  .pill.live{color:var(--live);border-color:#23461f}
  .pill.dead{color:var(--dead);border-color:#5c1f1c}
  .pill.limited{color:var(--limited);border-color:#5c4a17}
  main{padding:22px;max-width:1280px;margin:0 auto}
  .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px;margin-bottom:22px}
  .card{background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:16px}
  .card .lbl{color:var(--dim);font-size:12px;text-transform:uppercase;letter-spacing:.04em}
  .card .val{font-size:26px;font-weight:700;margin-top:4px}
  .card .sub{color:var(--dim);font-size:12px;margin-top:2px}
  section{background:var(--panel);border:1px solid var(--border);border-radius:12px;margin-bottom:22px;overflow:hidden}
  .sec-head{display:flex;align-items:center;gap:10px;padding:13px 18px;border-bottom:1px solid var(--border)}
  .sec-head h2{font-size:14px;margin:0;font-weight:650}
  .sec-head .spacer{flex:1}
  table{width:100%;border-collapse:collapse;font-size:13px}
  th{text-align:left;color:var(--dim);font-weight:600;padding:9px 14px;border-bottom:1px solid var(--border);font-size:12px;white-space:nowrap}
  td{padding:9px 14px;border-bottom:1px solid #20262f;vertical-align:middle}
  tr:last-child td{border-bottom:none}
  .dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px}
  .dot.live{background:var(--live)} .dot.dead{background:var(--dead)} .dot.limited{background:var(--limited)} .dot.unknown{background:var(--dim)}
  .mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}
  .bar{height:6px;border-radius:3px;background:#222b36;overflow:hidden;min-width:80px}
  .bar > i{display:block;height:100%;background:var(--accent)}
  button{background:var(--panel2);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:6px 12px;font-size:13px;cursor:pointer}
  button:hover{border-color:var(--accent)}
  button.primary{background:var(--accent);border-color:var(--accent);color:#fff}
  button.sm{padding:3px 9px;font-size:12px}
  input{background:var(--bg);border:1px solid var(--border);color:var(--text);border-radius:8px;padding:7px 10px;font-size:13px}
